fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut flash: i32 = host::display::state_get(3);
    let mut zoom: i32 = host::display::state_get(2);
    if down == 1 && prev == 0 {
        let last: i32 = host::display::state_get(1);
        let now: i32 = t + 1;
        if last != 0 && now - last <= 18 {
            zoom = 1 - zoom;
            host::display::state_set(2, zoom);
            flash = 24;
            host::display::state_set(1, 0);
        } else {
            host::display::state_set(1, now);
        }
    }
    if flash > 0 { flash = flash - 1; }
    host::display::state_set(3, flash);
    host::display::state_set(0, down);
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x101018);
    let size: i32 = if zoom == 1 { 180 } else { 60 };
    host::display::fill_rect(w / 2 - size / 2, h / 2 - size / 2, size, size, 0x00aaff);
    if flash > 0 {
        host::display::draw_string(w / 2 - 60, 30, "DOUBLE TAP", 0xffff00, 2);
    }
    host::display::draw_string(8, h - 20, "DOUBLE TAP TO ZOOM", 0x808080, 1);
    host::display::present();
}
